, "secondBlock": [{"type": "lead", "text": "Confira todas as vantagens que você pode aproveitar:"}, {"type": "check_list", "items": ["5% de desconto extra em produtos selecionados nos supermercados participantes.", "Até 40 dias para pagar suas compras.", "Aceitação Visa em milhões de estabelecimentos no Brasil e no mundo.", "Até 70% de desconto em saúde em consultas, exames e medicamentos pelo programa Você Bem.", "Mais praticidade para acompanhar seu cartão e consultar sua fatura pelo aplicativo."]}, {"type": "closing", "text": "Não deixe essas vantagens para depois. Peça agora seu cartão +amigo e aproveite muito mais!"}]}]}$payload$::jsonb;
  email jsonb;
  base public.dynamic_email_briefings%rowtype;
  existing public.dynamic_email_briefings%rowtype;
  data jsonb;
  source_info jsonb;
  new_id uuid;
  group_id uuid;
  ruler_id uuid;
  n integer;
  w integer;
  d integer;
  net_index integer;
  code text;
  key text;
  seq text;
  segment_name constant text := 'V2 TOPO DE FUNIL DINÂMICO';
  before_rows jsonb;
  after_rows jsonb;
begin
  -- Lock only this ruler's rows while inheriting the approved fields.
  perform 1 from public.dynamic_email_briefings
    where partner='Plurix' and segment=segment_name and status <> 'archived' for update;
  select jsonb_agg(to_jsonb(b) order by b.id) into before_rows
    from public.dynamic_email_briefings b
    where partner='Plurix' and segment=segment_name and status <> 'archived'
      and briefing_data->>'SEQUENCIA' in ('E-mail 1','E-mail 2','E-mail 3','E-mail 4');
  if (select count(*) from public.dynamic_email_briefings
      where partner='Plurix' and segment=segment_name and status <> 'archived'
        and briefing_data->>'SEQUENCIA' in ('E-mail 1','E-mail 2')) <> 12 then
    raise exception 'Expected six approved network variants for E-mails 1 and 2';
  end if;
  select ruler_strategy_id into strict ruler_id from public.dynamic_email_email_strategies
    where partner='Plurix' and segment=segment_name and sequence='E-mail 1';
  for email in select value from jsonb_array_elements(payload->'emails') loop
    n := (email->>'number')::integer;
    w := (email->>'week')::integer;
    d := (email->>'day')::integer;
    seq := 'E-mail ' || n;
    code := 'S' || w || 'D0' || d;
    group_id := ('d2d20000-0000-4000-8000-0000000000e' || n)::uuid;
    if exists (select 1 from public.dynamic_email_email_strategies
      where partner='Plurix' and segment=segment_name and sequence=seq and campaign_group_id<>group_id) then
      raise exception 'Existing strategy has a different group for %', seq;
    end if;
    insert into public.dynamic_email_email_strategies
      (ruler_strategy_id,campaign_group_id,partner,segment,week_key,sequence,subject,preheader,
       technical_status,editorial_status,visual_status,certification_status,
       field_provenance,updated_by_type,update_source,change_reason,llm_model,functional_name)
    values (ruler_id,group_id,'Plurix',segment_name,'Semana '||w,seq,
      email->'patch'->>'ASSUNTO',email->'patch'->>'PRE_CABECALHO',
      'draft','draft','needs_review','not_tested',
      jsonb_build_object('source',payload->>'source','sha256',payload->>'sha256','section',1),
      'llm','llm','Briefings de marketing; padrão dos E-mails 1 e 2 confirmado por Pablo em 09/11/2026.',
      'Codex','V2 TOPO DINÂMICO · '||seq)
    on conflict (campaign_group_id) do nothing;
    net_index := 0;
    for base in select * from public.dynamic_email_briefings
      where partner='Plurix' and segment=segment_name and status <> 'archived'
        and briefing_data->>'SEQUENCIA' = 'E-mail ' || d
      order by briefing_data->>'NM_PRODUTO_INTERNO' loop
      net_index := net_index + 1;
      if base.template_slot_id <> 'builtin-plurix-v13'
        or base.briefing_data->>'TP_CAMPANHA' <> 'Topo de Funil' then
        raise exception 'Unexpected baseline template/campaign';
      end if;
      new_id := ('d2d20000-0000-4000-8000-' || lpad((100+(n-1)*10+net_index)::text,12,'0'))::uuid;
      data := base.briefing_data || (email->'patch') || jsonb_build_object(
        '__id',new_id::text,'SEQUENCIA',seq,'__journeyConfirmed',false);
      foreach key in array array['LINK_CTA_1','LINK_CTA_2','LINK_BANNER_1_CORPO','LINK_BANNER_2_CORPO'] loop
        if coalesce(data->>key,'') !~ '^https://.*S[0-9]+D[0-9]+' then
          raise exception 'Missing approved tracking pattern: % / %',base.id,key;
        end if;
        data := jsonb_set(data,array[key],to_jsonb(
          replace(regexp_replace(data->>key,'S[0-9]+D[0-9]+',code,'g'),'af_sub2=s1','af_sub2=s'||w)));
      end loop;
      if coalesce(data->>'UTM_CAMPANHA','') !~ '_SEMANA[0-9]+_EMAIL[0-9]+_' then
        raise exception 'Missing approved UTM pattern';
      end if;
      data := jsonb_set(data,'{UTM_CAMPANHA}',to_jsonb(regexp_replace(
        data->>'UTM_CAMPANHA','_SEMANA[0-9]+_EMAIL[0-9]+_','_SEMANA'||w||'_EMAIL'||n||'_')));
      source_info := jsonb_build_object('source',payload->>'source','sha256',payload->>'sha256',
        'section',1,'importKey',segment_name||'|'||seq||'|'||(data->>'NM_PRODUTO_INTERNO'),
        'baselineId',base.id,'baselineVersion',base.version,'secondBlock',email->'secondBlock');
      select * into existing from public.dynamic_email_briefings
        where partner='Plurix' and segment=segment_name and status <> 'archived'
          and briefing_data->>'SEQUENCIA'=seq
          and briefing_data->>'NM_PRODUTO_INTERNO'=data->>'NM_PRODUTO_INTERNO';
      if found then
        if existing.id<>new_id or existing.briefing_data is distinct from data then
          raise exception 'Existing content differs; refusing overwrite: % / %',seq,data->>'NM_PRODUTO_INTERNO';
        end if;
      else
        insert into public.dynamic_email_briefings
          (id,briefing_data,partner,segment,subgroup,week_key,activity_names,campaign_group_id,
           status,version,template_slot_id,journey_confirmed,import_source)
        values (new_id,data,'Plurix',segment_name,base.subgroup,'Semana '||w,array[]::text[],group_id,
          'draft',1,base.template_slot_id,false,source_info);
        insert into public.dynamic_email_briefing_versions
          (briefing_id,version,snapshot,change_summary,warnings)
        values (new_id,1,data,'Briefing marketing compilado; links e identidade herdados dos E-mails 1/2.',
          '["Preview/Test Send SFMC pendente"]'::jsonb);
      end if;
    end loop;
    if net_index<>6 then raise exception 'Expected six networks for %',seq; end if;
  end loop;
  select jsonb_agg(to_jsonb(b) order by b.id) into after_rows
    from public.dynamic_email_briefings b
    where partner='Plurix' and segment=segment_name and status <> 'archived'
      and briefing_data->>'SEQUENCIA' in ('E-mail 1','E-mail 2','E-mail 3','E-mail 4');
  if before_rows is distinct from after_rows then raise exception 'E-mails 1-4 changed'; end if;
  if (select count(*) from public.dynamic_email_briefings
    where partner='Plurix' and segment=segment_name and status <> 'archived'
      and briefing_data->>'SEQUENCIA' in ('E-mail 5','E-mail 6','E-mail 7','E-mail 8')) <> 24 then
    raise exception 'Expected 24 new drafts';
  end if;
end
$release$;
